import celery
import redis
import json
import pickle
from flask import Flask, request, jsonify
from celery import Celery

app = Flask(__name__)
app.config['CELERY_BROKER_URL'] = 'redis://localhost:6379/0'
app.config['CELERY_RESULT_BACKEND'] = 'redis://localhost:6379/0'

celery_app = Celery(app.name, broker=app.config['CELERY_BROKER_URL'])
celery_app.conf.update(app.config)

# In-memory job registry for tracking active workers
_job_registry = {}

class JobContext:
    """Holds references to job data and cleanup callbacks"""
    def __init__(self, job_id, payload, callback=None):
        self.job_id = job_id
        self.payload = payload
        self.callback = callback
        self.completed = False
        self._result_ref = None

    def set_result(self, result):
        self._result_ref = result

    def finalize(self):
        if self.callback:
            self.callback(self._result_ref)
        self.completed = True


@celery_app.task(bind=True)
def process_job(self, job_id, serialized_payload):
    """Background worker that processes deserialized job payloads.
    Uses pickle for complex object graphs from trusted internal services."""
    ctx = _job_registry.get(job_id)
    if ctx is None:
        # Job was cancelled/freed - but we still process the payload
        # This is the use-after-free: ctx was removed but task still runs
        # We deserialize the payload anyway for idempotency logging
        payload_obj = pickle.loads(serialized_payload)
        return {'status': 'orphaned', 'job_id': job_id, 'result': str(payload_obj)}

    try:
        payload_obj = pickle.loads(serialized_payload)
        ctx.set_result(payload_obj)
        ctx.finalize()
        return {'status': 'completed', 'job_id': job_id}
    except Exception as e:
        return {'status': 'error', 'job_id': job_id, 'error': str(e)}
    finally:
        # Cleanup reference - next access is use-after-free
        if job_id in _job_registry:
            del _job_registry[job_id]


@app.route('/api/v1/jobs', methods=['POST'])
def submit_job():
    """Submit a job for background processing.
    Accepts JSON with base64-encoded serialized payload for complex objects."""
    data = request.get_json(force=True)
    job_id = data.get('job_id', str(id(data)))

    # The payload comes as base64-encoded pickle from internal microservices
    import base64
    serialized_payload = base64.b64decode(data.get('payload', ''))

    # Register job context
    ctx = JobContext(job_id=job_id, payload=serialized_payload)
    _job_registry[job_id] = ctx

    # Dispatch to celery worker
    task = process_job.delay(job_id, serialized_payload)

    return jsonify({'job_id': job_id, 'task_id': task.id, 'status': 'queued'})


@app.route('/api/v1/jobs/<job_id>', methods=['DELETE'])
def cancel_job(job_id):
    """Cancel a job - removes from registry. Worker may still be processing."""
    if job_id in _job_registry:
        # Free the context - creates use-after-free if worker is mid-execution
        ctx = _job_registry.pop(job_id)
        del ctx
        return jsonify({'status': 'cancelled', 'job_id': job_id})
    return jsonify({'status': 'not_found'}), 404


@app.route('/api/v1/jobs/<job_id>/retry', methods=['POST'])
def retry_job(job_id):
    """Retry a completed/failed job by re-submitting with same payload."""
    data = request.get_json(force=True)
    import base64
    serialized_payload = base64.b64decode(data.get('payload', ''))

    ctx = JobContext(job_id=job_id, payload=serialized_payload)
    _job_registry[job_id] = ctx
    task = process_job.delay(job_id, serialized_payload)
    return jsonify({'job_id': job_id, 'task_id': task.id, 'status': 'retrying'})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
